def eval_rpn(tokens):
    """Evaluate a reverse Polish expression given as a list of strings."""
    st = []
    for t in tokens:
        if t in ("+", "-", "*", "/"):
            b = st.pop()
            a = st.pop()
            if t == "+":
                st.append(a + b)
            elif t == "-":
                st.append(b - a)
            elif t == "*":
                st.append(a * b)
            else:
                st.append(b / a)
        else:
            st.append(float(t))
    if len(st) != 1:
        raise ValueError("bad expression")
    return st[0]

