class TTLCache:
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock
        self.d = {}

    def set(self, key, value, ttl=None):
        self.d[key] = (value, self.clock.now() + (self.ttl if ttl is None else ttl))

    def _live(self, key):
        e = self.d.get(key)
        if e is None:
            return None
        if self.clock.now() >= e[1]:
            del self.d[key]
            return None
        return e

    def get(self, key, default=None):
        e = self._live(key)
        return default if e is None else e[0]

    def __len__(self):
        return sum(1 for k in list(self.d) if self._live(k) is not None)

    def purge(self):
        n = len(self.d)
        for k in list(self.d):
            self._live(k)
        return n - len(self.d)

