def plan(tasks):
    by = {t.name: t for t in tasks}
    for t in tasks:
        for d in t.deps:
            if d not in by:
                raise ValueError('unknown dep ' + d)
    sched = {}
    state = {}

    def visit(name):
        if name in sched:
            return
        if state.get(name) == 1:
            raise ValueError('cycle')
        state[name] = 1
        t = by[name]
        for d in t.deps:
            visit(d)
        start = max((sched[d][1] for d in t.deps), default=0)
        sched[name] = (start, start + t.duration)
        state[name] = 2
    for n in sorted(by):
        visit(n)
    if not sched:
        return {}, []
    cur = min(sched, key=lambda n: (-sched[n][1], n))
    path = [cur]
    while by[cur].deps:
        cur = min((d for d in by[cur].deps if sched[d][1] == sched[cur][0]), key=lambda n: n)
        path.append(cur)
    return sched, path[::-1]

