def solve(board):
    g = [[0 if c == '.' else int(c) for c in row] for row in board]
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    box = [set() for _ in range(9)]
    for r in range(9):
        for c in range(9):
            d = g[r][c]
            if d:
                b = r // 3 * 3 + c // 3
                if d in rows[r] or d in cols[c] or d in box[b]:
                    return None
                rows[r].add(d); cols[c].add(d); box[b].add(d)
    empties = [(r, c) for r in range(9) for c in range(9) if not g[r][c]]

    def go():
        best, bo = None, None
        for r, c in empties:
            if g[r][c]:
                continue
            opts = [d for d in range(1, 10) if d not in rows[r] and d not in cols[c] and d not in box[r // 3 * 3 + c // 3]]
            if best is None or len(opts) < len(bo):
                best, bo = (r, c), opts
                if not opts:
                    return False
        if best is None:
            return True
        r, c = best
        b = r // 3 * 3 + c // 3
        for d in bo:
            g[r][c] = d
            rows[r].add(d); cols[c].add(d); box[b].add(d)
            if go():
                return True
            g[r][c] = 0
            rows[r].discard(d); cols[c].discard(d); box[b].discard(d)
        return False
    if not go():
        return None
    return [''.join(map(str, row)) for row in g]

