class Graph:
    def __init__(self):
        self.adj = {}

    def add_edge(self, u, v, w=1):
        if w <= 0:
            raise ValueError("weight must be positive")
        self.adj.setdefault(u, {})[v] = w
        self.adj.setdefault(v, {})[u] = w

    def weight(self, u, v):
        return self.adj[u][v]

    def remove_edge(self, u, v):
        if v not in self.adj.get(u, {}):
            raise KeyError((u, v))
        del self.adj[u][v]
        del self.adj[v][u]

    def neighbors(self, u):
        return sorted(self.adj.get(u, ()))

    def cheapest(self, src, dst):
        import heapq
        if src not in self.adj or dst not in self.adj:
            return None
        best = {}
        h = [(0, 1, [src])]
        while h:
            cost, hops, path = heapq.heappop(h)
            u = path[-1]
            if u in best:
                continue
            best[u] = (cost, path)
            if u == dst:
                return cost, path
            for v in self.adj[u]:
                if v not in best:
                    heapq.heappush(h, (cost + self.adj[u][v], hops + 1, path + [v]))
        return None

    def hops(self, src, dst):
        """Fewest edges between src and dst, or -1."""
        if src not in self.adj or dst not in self.adj:
            return -1
        seen, q = {src}, deque([(src, 0)])
        while q:
            u, d = q.popleft()
            if u == dst:
                return d
            for v in self.neighbors(u):
                if v not in seen:
                    seen.add(v)
                    q.append((v, d + 1))
        return -1

