class IntervalSet:
    """A set of integers stored as sorted, disjoint, non-adjacent half-open ranges [start, end)."""

    def __init__(self):
        self.ranges = []

    def add(self, start, end):
        if start >= end:
            return
        out = []
        placed = False
        for s, e in self.ranges:
            if e < start:
                out.append((s, e))
            elif s > end:
                if not placed:
                    out.append((start, end))
                    placed = True
                out.append((s, e))
            else:
                start, end = min(start, s), max(end, e)
        if not placed:
            out.append((start, end))
        self.ranges = out

    def __contains__(self, x):
        return any(s <= x < e for s, e in self.ranges)

    def total(self):
        return sum(e - s for s, e in self.ranges)

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self.ranges:
            if e <= start or s >= end:
                out.append((s, e))
                continue
            if s < start:
                out.append((s, start))
            if e > end:
                out.append((end, e))
        self.ranges = out

    def intersection(self, other):
        res = IntervalSet()
        for s, e in self.ranges:
            for s2, e2 in other.ranges:
                lo, hi = max(s, s2), min(e, e2)
                if lo < hi:
                    res.add(lo, hi)
        return res

    def union(self, other):
        res = IntervalSet()
        for s, e in self.ranges + other.ranges:
            res.add(s, e)
        return res

    def gaps(self, lo, hi):
        out = []
        cur = lo
        for s, e in self.ranges:
            if e <= cur:
                continue
            if s >= hi:
                break
            if s > cur:
                out.append((cur, s))
            cur = max(cur, e)
        if cur < hi:
            out.append((cur, hi))
        return out

    def __eq__(self, other):
        return isinstance(other, IntervalSet) and self.ranges == other.ranges

