class TrieNode:
    def __init__(self):
        self.kids = {}
        self.end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def add(self, word):
        node = self.root
        for ch in word:
            node = node.kids.setdefault(ch, TrieNode())
        node.end = True

    def has(self, word):
        node = self.root
        for ch in word:
            node = node.kids.get(ch)
            if node is None:
                return False
        return node.end

    def search(self, pattern):
        level = [self.root]
        for ch in pattern:
            nxt = []
            for node in level:
                if ch == ".":
                    nxt.extend(node.kids.values())
                elif ch in node.kids:
                    nxt.append(node.kids[ch])
            level = nxt
            if not level:
                return False
        return bool(pattern) and any(n.end for n in level)

    def with_prefix(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.kids.get(ch)
            if node is None:
                return []
        out, st = [], [(node, prefix)]
        while st:
            n, w = st.pop()
            if n.end:
                out.append(w)
            for ch, k in n.kids.items():
                st.append((k, w + ch))
        return sorted(out)

    def longest_common_prefix(self):
        node, out = self.root, []
        while len(node.kids) == 1 and not node.end:
            ch, node = next(iter(node.kids.items()))
            out.append(ch)
        return "".join(out)

