import math

AREA_FUNCS = {
    "circle": lambda r: math.pi * r ** 2,
    "square": lambda s: s ** 2,
    "rect": lambda w, h: w * h,
    "triangle": lambda b, h: 0.5 * b * h,
    "ellipse": lambda a, b: math.pi * a * b,
}


def register(kind, fn):
    AREA_FUNCS[kind] = fn


def area(kind, *dims):
    if kind not in AREA_FUNCS:
        raise ValueError("unknown shape: " + kind)
    return AREA_FUNCS[kind](*dims)

