class Timer:
    def __init__(self, clock):
        self.clock = clock
        self.elapsed = None
        self._start = None

    def __enter__(self):
        self._start = self.clock.now()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.elapsed = self.clock.now() - self._start
        return False


