import functools


def memoize(fn):
    @functools.wraps(fn)
    def wrapper(*args):
        if args in wrapper.cache:
            return wrapper.cache[args]
        wrapper.calls += 1
        r = fn(*args)
        wrapper.cache[args] = r
        return r
    wrapper.cache = {}
    wrapper.calls = 0
    return wrapper


